    // access won in round 2. Share of that access withdrawn: contesting the major finding a quarter, contesting all
    // half, and half more when the round 2 negotiation left the relationship strained (the case: parks run on state
    // permits, and after Gorgona made the press the Ministry must show it protects them).
    var AVENTURA_ACCESS_WITHDRAWN = { full_acceptance: 0, partial_contest: 0.25, full_contest: 0.5, strained: 0.5 };

    class AventuraAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Turismo de Aventura en Colombia';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
