        getChartData(state) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var labels = state.domainState.ebitdaHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                financeChart: {
                    labels: labels,
                    datasets: [{ label: T('chart_ebitda_label'), data: state.domainState.ebitdaHistory }]
                },
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { label: T('env_label'), data: state.domainState.envHistory },
                        { label: T('reputation_label'), data: state.domainState.repHistory }
                    ]
                }
