        getPerformanceSummary(history) {
            if (!history.length) return {};
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var lastRecord = history[history.length - 1];
            var r = lastRecord.results || {};
            var totalEbitda = history.reduce(function(s, h) { return s + (h.results ? h.results.ebitda : 0); }, 0);
            var finalCash = r.cash || 0;
            var finalEnv = r.envScore || 0;
            var finalRep = r.reputation || 0;
            var compositeScore = Math.round(aventuraCashPoints(finalCash) + (finalEnv * 0.4) + (finalRep * 0.35));

            // The label follows the composite score alone, so a higher label never comes with a lower score. The
            // board judges the year by final cash, environmental score and reputation, and the composite already
            // weighs all three; the extra conditions on total EBITDA, env and reputation could give Exceptional at 85
            // and Excellent at 95.
            // Thresholds anchored on the play the case supports (2026-10-08): expansion on the base plan, a
            // collaborative negotiation, accepting and remediating the findings, organic growth and the industry
            // standard score 93, and every single different choice scores 91 or less, so Exceptional (92) needs all
            // five. Plays at random score 59 to 81 (p10 to p90) and land mostly in Competent and Good.
            var performance = T('perf_beginner');
            if (compositeScore >= 60) performance = T('perf_competent');
            if (compositeScore >= 70) performance = T('perf_good');
            if (compositeScore >= 80) performance = T('perf_excellent');
            if (compositeScore >= 92) performance = T('perf_exceptional');

            var insights = [];
            if (finalEnv >= 85) insights.push(T('insight_env_excellent'));
            if (finalEnv < 60) insights.push(T('insight_env_low'));
            if (finalRep >= 80) insights.push(T('insight_rep_good'));
            if (finalRep < 50) insights.push(T('insight_rep_low'));
            if (totalEbitda > 200) insights.push(T('insight_fin_strong'));
            if (totalEbitda < -800) insights.push(T('insight_fin_weak'));
            if (finalCash < 500) insights.push(T('insight_cash_low'));
            else if (finalCash < 4 * (1300 - 864)) insights.push(T('insight_cash_runway'));

            return {
                compositeScore: compositeScore,
                totalEbitda: totalEbitda,
                finalCash: finalCash,
                finalEnvScore: finalEnv,
                finalReputation: finalRep,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var period = results.period;
            if (period === 2 && results.relationStrained) return window.mySimulation.t('hint_relation_strained');
            if (period === 3 && results.accessWithdrawn > 0) return window.mySimulation.t('hint_access_withdrawn');
            if (period === 3 && results.findingsOpen > 0) return window.mySimulation.t('hint_findings_open');
            if (period < 4 && results.guideCapped) return window.mySimulation.t('hint_guide_capacity');
            if (period === 1 && results.ebitda < -400) return window.mySimulation.t('hint_deep_loss');
            if (period === 1 && results.guides < 15) return window.mySimulation.t('hint_few_guides');
            if (period === 2 && state.domainState.laCaleraCap < 0.5) return window.mySimulation.t('hint_low_access');
            if (period === 3 && results.envScore < 60) return window.mySimulation.t('hint_env_risk');
            if (period === 3 && results.reputation < 55) return window.mySimulation.t('hint_rep_risk');
            if (period === 4 && typeof results.sustainFunded === 'number' && results.sustainFunded < 1) return window.mySimulation.t('hint_excellence_cut');
            if (results.guideCapped) return window.mySimulation.t('hint_guide_capacity');
            if (period === 4 && results.ebitda > 0) return window.mySimulation.t('hint_recovery');
            if (results.cash < 500) return window.mySimulation.t('hint_cash_low');
            return null;
        }

