        _renderCompletion(state) {
            var panel = document.getElementById('resultsPanel');
            var body = document.getElementById('resultsBody');
            if (!panel || !body) return;
            var summary = {};
            try { summary = this.getPerformanceSummary(state.history || []) || {}; } catch (e) { summary = {}; }
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var comp = (summary.compositeScore != null) ? summary.compositeScore : 0;
            var perf = summary.performance || '';
            var teb = (summary.totalEbitda != null) ? summary.totalEbitda : 0;
            var fc = (summary.finalCash != null) ? summary.finalCash : 0;
            var insights = summary.insights || [];
            var html = '<div class="aventura-results-grid">';
            html += '<div class="aventura-result-metric"><span class="ar-label">' + T('composite_label') + '</span><span class="ar-value">' + comp + '/100</span></div>';
            html += '<div class="aventura-result-metric"><span class="ar-label">' + T('performance_label') + '</span><span class="ar-value">' + perf + '</span></div>';
            html += '<div class="aventura-result-metric"><span class="ar-label">' + T('total_ebitda_label') + '</span><span class="ar-value">COP ' + Math.round(teb).toLocaleString() + 'M</span></div>';
            html += '<div class="aventura-result-metric"><span class="ar-label">' + T('final_cash_label') + '</span><span class="ar-value">COP ' + Math.round(fc).toLocaleString() + 'M</span></div>';
            html += '</div>';
            if (insights.length) { html += '<p class="aventura-insights-title"><b>' + T('key_insights_label') + '</b></p><ul class="aventura-insights">'; for (var i = 0; i < insights.length; i++) { html += '<li>' + insights[i] + '</li>'; } html += '</ul>'; }
            body.innerHTML = html;
            panel.style.display = 'block';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var desc = window.mySimulation ? (window.mySimulation.t(round.descKey) || round.descFallback) : round.descFallback;
                briefEl.innerHTML = desc;
            }

            var badgeEl = document.getElementById('roundBadge');
            if (badgeEl) {
                var title = window.mySimulation ? (window.mySimulation.t(round.titleKey) || round.titleFallback) : round.titleFallback;
                badgeEl.textContent = title;
            }

            for (var p = 1; p <= 4; p++) {
                var panel = document.getElementById('decisionPanel' + p);
                if (panel) {
                    panel.style.display = (p === round.panel) ? 'block' : 'none';
                }
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new AventuraAdapter(), {
            simulationType: 'aventura_colombia_705',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
